 ('ENT-RUT-77096794-5','B2B2C','AMBOS','SPREAD_FX',0.999::numeric,0.999::numeric,0.99::numeric,'Global66 ofrece Cuenta Global para personas y Global66 Empresas/Business para compañías con pagos, cobros, FX y tesorería.','El sitio oficial declara más de 2,5 millones de personas y más de 10.000 empresas LATAM operando con la plataforma.','Global66 declara que en transferencias internacionales su costo principal es un margen/costo sobre el tipo de cambio, visible antes de confirmar.','https://www.global66.com/cl/'),
 ('ENT-RUT-77977667-0','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'Haulmer/TUU desarrolla soluciones de pagos, facturación y tecnología para emprendedores, micro, pequeños y medianos negocios.','La contratación TUU se dirige a comercios y negocios que reciben pagos con tarjetas.','Los términos TUU 2026 establecen tarifas por plan/transacción y margen adquirente/PSP; el sitio publica comisión para crédito y débito.','https://www.haulmer.com/legal/terminos-y-condiciones-de-servicio-del-ecosistema-tuu/'),
 ('ENT-RUT-77268674-9','B2B','EMPRESAS',null,0.999::numeric,0.999::numeric,null,'Pomelo provee infraestructura de emisión, procesamiento y rieles de pagos mediante integración tecnológica para bancos, fintechs y empresas.','La oferta se dirige a organizaciones que lanzan productos financieros, programas de tarjetas y soluciones de pagos.',null,'https://www.pomelo.la/blog/tarjetas-globales-pomelo-global-card'),
 ('ENT-RUT-77126383-6','B2B','EMPRESAS',null,0.999::numeric,0.999::numeric,null,'Toku se presenta como infraestructura de pagos, recaudación y agentes para grandes empresas.','El producto está dirigido explícitamente a empresas y grandes organizaciones de múltiples industrias.',null,'https://trytoku.com/'),
 ('ENT-RUT-76967692-9','B2C','PERSONAS',null,0.999::numeric,0.999::numeric,null,'Tenpo ofrece cuenta digital, tarjetas, pagos, inversiones, seguros y billetera en dólares para clientes personas.','La oferta principal observada está dirigida a personas/clientes individuales.',null,'https://www.tenpo.cl/una-cuenta-muy-tu'),
 ('ENT-RUT-76584147-K','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.98::numeric,0.98::numeric,0.98::numeric,'Payku opera una pasarela/API de pagos y recaudación integrable a tiendas y comercios, con payouts y pagos recurrentes.','La documentación oficial de integración exige una tienda/comercio y cuentas Payku para procesar pagos.','Documentos tributarios alojados por Payku describen servicio de pago/recaudación y comisiones payout como conceptos cobrados.','https://cdn.payku.cl/public/ecommerce-plugins/jumpseller/manualjumpseller.pdf'),
 ('ENT-RUT-99584660-8','B2B','EMPRESAS','COMISION_TRANSACCIONAL',0.999::numeric,0.999::numeric,0.999::numeric,'PayU presta procesamiento, validación y transferencia de pagos a comercios.','Los términos chilenos regulan explícitamente el uso de PayU por comercios.','Los términos de comercios establecen tarifas cobradas por los servicios PayU.','https://chile.payu.com/wp-content/uploads/sites/4/2020/04/T%C3%89RMINOS-Y-CONDICIONES-GENERALES-DE-USO-PARA-COMERCIOS-PAYU.pdf')
), logged as (
 select v.fintech_id,'MANUAL_OFFICIAL_PAYMENTS_2026_09_09',v.business_model,v.bm_conf,v.target_customer,v.tc_conf,coalesce(v.revenue_model,e.revenue_model),coalesce(v.rev_conf,e.revenue_model_confidence),1,now(),jsonb_build_object('source_url',v.source_url,'business_model_basis',v.bm_basis,'target_customer_basis',v.tc_basis,'revenue_model_basis',v.rev_basis,'manual_validation',true,'cohort','PAYMENTS')
 from vals v join public.aml_fintech_entity e using(fintech_id)
 returning fintech_id
)
update public.aml_fintech_entity e
set business_model=v.business_model,target_customer=v.target_customer,revenue_model=coalesce(v.revenue_model,e.revenue_model),business_model_basis=v.bm_basis,business_model_confidence=v.bm_conf,target_customer_basis=v.tc_basis,target_customer_confidence=v.tc_conf,revenue_model_basis=case when v.revenue_model is not null then v.rev_basis else e.revenue_model_basis end,revenue_model_confidence=case when v.revenue_model is not null then v.rev_conf else e.revenue_model_confidence end,profile_classifier_version='MANUAL_OFFICIAL_PAYMENTS_2026_09_09',profile_refreshed_at=now(),refreshed_at=now()
from vals v
where e.fintech_id=v.fintech_id and exists(select 1 from logged l where l.fintech_id=e.fintech_id);

